  Lemma L_9e8 : forall m (x1 x5 x6 x7 x12 x13 x14 x15 x16 x17 x19 x24 x25 x26 x27 x31 : word) fc K
      (ws : list word) (big : list Z) (lo a r rp z zm e p2 t2 pp p3 t3 : Z),
    midw K m fc 0%Z ->
    u32arr rsegs m (bv_unsigned sp + -1056) ws -> length ws = 128%nat ->
    length big = 128%nat -> (forall i, (lo <= i < zm)%Z -> znth big i = wval ws i) ->
    (forall i, (zm <= i)%Z -> znth big i = 0%Z) ->
